def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                x, y = stack.pop()
                cells.add((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w
                            and (nx, ny) not in seen
                            and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append((color, cells))

    frames = []
    for color, cells in components:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        top, bottom = min(rs), max(rs)
        left, right = min(cs), max(cs)
        if bottom - top < 2 or right - left < 2:
            continue
        perimeter = {
            (r, c)
            for r in range(top, bottom + 1)
            for c in range(left, right + 1)
            if r in (top, bottom) or c in (left, right)
        }
        if cells == perimeter:
            frames.append((color, cells, top, left, bottom, right))

    out = [[bg] * w for _ in range(h)]
    for color, cells, top, left, bottom, right in frames:
        for r, c in cells:
            out[r][c] = color

        n = sum(1 for other_color, other_cells in components
                if other_color == color and other_cells is not cells)
        for i in range(n):
            r = (top + bottom) // 2
            c = right - 2 - 2 * i
            if left < c < right:
                out[r][c] = color

    return out
